const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Manitoba, Canada geometry
  const manitoba = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'Canada'),
      ee.Filter.eq('ADM1_NAME', 'Manitoba')
    ));

  // 2. Get Manitoba geometry
  const manitobaGeom = manitoba.geometry();

  // 3. Define date range for August 3, 2025
  const startDate = '2025-08-03';
  const endDate = '2025-08-04';

  // 4. Load FIRMS fire data (MODIS active fire product)
  let fireCollection = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(manitobaGeom);

  // Check if collection has data
  const collectionSize = fireCollection.size().getInfo();
  console.log(`Fire images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try VIIRS as fallback
    fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(manitobaGeom);

    const fallbackSize = fireCollection.size().getInfo();
    console.log(`Fallback collection size: ${fallbackSize}`);

    if (fallbackSize === 0) {
      console.log("No fire data available for August 3, 2025");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 5. Process fire detections
  const fireImage = fireCollection.first();
  const fireMask = fireImage.select('FireMask');

  // FireMask values: 7-9 are fire pixels (7=low, 8=nominal, 9=high confidence)
  const activeFires = fireMask.gte(7).and(fireMask.lte(9));

  // 6. Count fire pixels in Manitoba
  const fireCount = activeFires.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: manitobaGeom,
    scale: 1000,
    maxPixels: 1e9
  });

  const firePixels = fireCount.get('FireMask').getInfo();

  if (firePixels === null || firePixels === undefined) {
    console.log("Fire count calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Active fire pixels detected: ${firePixels}`);

  // 7. Determine answer
  if (firePixels > 30) {
    console.log("More than 30 fires detected");
    console.log("<answer>A</answer>");
  } else {
    console.log("30 or fewer fires detected");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
